// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(this).balance);
        uint256 beforeDeposits = c.depositsCount();
        bool ok;
        (ok, ) = address(c).call{value: amount}("");
        uint256 afterDeposits = c.depositsCount();
        assertTrue(ok && afterDeposits == beforeDeposits + 1);
    }
}
